#!/usr/bin/env python3
"""
Script to verify network connectivity by attempting to connect to a well-known host.
"""

import sys
import socket
import subprocess
from typing import Tuple, Optional

# Configuration
HOST_TO_CHECK = "8.8.8.8"  # Google DNS
PORT_TO_CHECK = 53  # DNS port
TIMEOUT_SECONDS = 5


def check_socket_connectivity(host: str, port: int, timeout: int) -> Tuple[bool, Optional[str]]:
    """Check connectivity to a host and port using socket connection."""
    try:
        sock = socket.create_connection((host, port), timeout=timeout)
        sock.close()
        return True, None
    except socket.timeout:
        return False, f"Connection timed out after {timeout} seconds"
    except socket.gaierror:
        return False, f"Could not resolve hostname {host}"
    except ConnectionRefusedError:
        return False, f"Connection refused by {host}:{port}"
    except Exception as e:
        return False, f"Connection failed: {str(e)}"

def check_ping_connectivity(host: str, timeout: int) -> Tuple[bool, Optional[str]]:
    """Check connectivity using ping command."""
    try:
        result = subprocess.run(
            ["ping", "-c", "1", "-W", str(timeout), host],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=timeout + 2
        )
        if result.returncode == 0:
            return True, None
        else:
            return False, f"Ping to {host} failed with return code {result.returncode}"
    except subprocess.TimeoutExpired:
        return False, f"Ping to {host} timed out"
    except FileNotFoundError:
        return False, "Ping command not found"
    except Exception as e:
        return False, f"Ping failed: {str(e)}"

def main() -> int:
    """Main function to check network connectivity."""
    print(f"Checking network connectivity to {HOST_TO_CHECK}:{PORT_TO_CHECK}...")

    # First try socket connection (more reliable)
    success, error = check_socket_connectivity(HOST_TO_CHECK, PORT_TO_CHECK, TIMEOUT_SECONDS)

    if success:
        print("✓ Socket connection successful")

        # Also try ping for additional verification
        ping_success, ping_error = check_ping_connectivity(HOST_TO_CHECK, TIMEOUT_SECONDS)
        if ping_success:
            print("✓ Ping successful")
        else:
            print(f"⚠ Ping failed: {ping_error}")

        print("Network connectivity check PASSED")
        return 0
    else:
        print(f"✗ {error}")

        # Try ping as fallback
        ping_success, ping_error = check_ping_connectivity(HOST_TO_CHECK, TIMEOUT_SECONDS)
        if ping_success:
            print("✓ Ping successful - basic connectivity exists")
            print("Network connectivity check PASSED (basic)")
            return 0
        else:
            if ping_error:
                print(f"✗ {ping_error}")

        print("Network connectivity check FAILED")
        return 1

if __name__ == "__main__":
    sys.exit(main())

